def _mergeOrderings(orderings):
    merged = []
    while orderings:
        for i, ordering in enumerate(orderings):
            if not merged or merged[-1] in ordering:
                merged.extend(ordering)
                orderings.pop(i)
                break
            else:
                if ordering[0] in merged:
                    merged.extend(ordering[ordering.index(merged[-1]):])
                    orderings.pop(i)
                    break
        else:
            raise ValueError("Orderings are not valid")
    return merged

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    used = set()
    for cls in classes:
        if cls not in used:
            minimal.append(cls)
            used.update(cls.__subclasses__())
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        for base in cls.__bases__:
            if base not in seen:
                seen.add(base)
                result.append(base)
    return tuple(result)

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """

    def is_subclass(sub, sup):
        while sub:
            if sub is sup:
                return True
            sub = sub.__bases__[0]
        return False

    base_order = []
    for cls in classes:
        if not any(is_subclass(cls, other) for other in base_order):
            base_order.append(cls)
            base_order.extend(cls.__bases__)

    return base_order

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    base_count = {}
    for cls in classes:
        for base in cls.__mro__:
            if base not in base_count:
                base_count[base] = 0
            base_count[base] += 1

    min_base = None
    min_count = float('inf')
    for base, count in base_count.items():
        if count < min_count:
            min_base = base
            min_count = count

    return [base for base in classes if base.__mro__.index(min_base) < base.__mro__.index(base)]

