            result[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            diff_dict = difference(d1[key], d2[key], level - 1)
            if diff_dict:
                result[key] = diff_dict
        elif d1[key] != d2[key]:
            result[key] = d1[key]
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.edges[0] or coord >= self.edges[-1]:
        return
    index = int((coord - self.edges[0]) / self.width)
    if index >= len(self.values):
        index -= 1
    self.values[index] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    import json

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__(json.dumps(messages))

    key_regex = re.compile(r'^[a-zA-Z0-9\$_.]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9]*$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({json.dumps(key): "expected string or bytes-like object"})
            continue

        if not key_regex.match(key):
            errors.append({key: "Label key '{}' does not match the regex".format(key)})

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({json.dumps(item): "expected string or bytes-like object"})
        elif not isinstance(value, str):
            errors.append({json.dumps(value): "expected string or bytes-like object"})
        elif not value_regex.match(value):
            errors.append({value: "Label value '{}' does not match the regex".format(value)})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    import re
    from django.core.exceptions import ValidationError

    error_messages = []

    key_regex = r'^[A-Za-z0-9_]+$'
    value_regex = r'^[A-Za-z0-9_]+$'

    for key, value in labels.items():
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str) and not isinstance(item, bytes):
                    error_messages.append({str(item): 'expected string or bytes-like object'})
        else:
            if not isinstance(key, (str, bytes)) and not isinstance(value, (str, bytes)):
                error_messages.append({key: 'expected string or bytes-like object'})

        if not isinstance(key, (str, bytes)) or not re.match(key_regex, key):
            error_messages.append({key: "Label key '%s' does not match the regex %s" % (key, key_regex)})

        if isinstance(value, (str, bytes)) and not re.match(value_regex, value):
            error_messages.append({value: "Label value '%s' does not match the regex %s" % (value, value_regex)})

    if error_messages:
        raise ValidationError({"messages": error_messages})

