def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        if isinstance(self.SQLParams.in_style, NamedParameterStyle):
            param_mapping = {f":{key}": value for key, value in params.items()}
        else:
            param_mapping = {f":{idx}": value for idx, value in enumerate(params)}

        formatted_sql = sql
        for original, formatted in param_mapping.items():
            formatted_sql = formatted_sql.replace(original, str(formatted))

        return formatted_sql, param_mapping

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    from ..sqlparams import SQLParams, SQLP

    # Convert each parameter set to out-style parameters
    formatted_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            # Named parameter style
            out_params = {f":{k}": v for k, v in params.items()}
        elif isinstance(params, Sequence):
            # Ordinal parameter style
            out_params = [v for v in params]
        else:
            raise ValueError("Invalid parameter type")

        formatted_params.append(out_params)

    # Convert SQL query to use out-style parameters
    formatter = SQLParams(out=sqlparse.mysql.placeholder)
    formatted_sql = formatter.format(sql, out_params)

    return formatted_sql, formatted_params

