from os.path import isfile, isdir, abspath, join, exists
from os import listdir as ls

def files_list(path):
    """
    Return the files in `path`
    """
    ret = []
    if exists(path):
        if isfile(path):
            ret.append(abspath(path))
        elif isdir(path):
            ret += [join(path, f) for f in ls(path)
                    if isfile(join(path, f))]
        else:
            raise FileNotFoundError(path)
    return ret

def _explore_folder(folder):
        """
        Get packages' data from folder

        Groups files by their XML basename and returns data in dict format.

        Parameters
        ----------
        folder : str
            Folder of the package
        Returns
        -------
        dict
        """
        packages = {}
        for root, _, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    basename = os.path.splitext(file)[0]
                    if basename in packages:
                        packages[basename].append(os.path.join(root, file))
                    else:
                        packages[basename] = [os.path.join(root, file)]

        return packages

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """

    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File {file_path} does not exist.")

    if lang not in ["original", "en"]:
        raise ValueError("Language must be either 'original' or 'en'.")

    base, ext = os.path.splitext(file_path)
    new_file_path = f"{base}-{lang}{ext}"

    try:
        shutil.copy(file_path, new_file_path)
        return new_file_path
    except IOError as e:
        raise IOError(f"Failed to copy file: {e}")

