def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify_and(e):
        if isinstance(e, And):
            if e[0] == e[1][0]:
                return e[0]
            elif isinstance(e[1], Or) and e[0] in e[1]:
                return e[0]
        return e

    def simplify_or(e):
        if isinstance(e, Or):
            if e[0] == e[1][0]:
                return e[0]
            elif isinstance(e[1], And) and e[0] in e[1]:
                return e[0]
        return e

    def apply_absorption(e):
        if isinstance(e, And):
            e[0] = apply_absorption(e[0])
            e[1] = apply_absorption(e[1])
            e[0] = simplify_and(e[0])
            e[1] = simplify_and(e[1])
        elif isinstance(e, Or):
            e[0] = apply_absorption(e[0])
            e[1] = apply_absorption(e[1])
            e[0] = simplify_or(e[0])
            e[1] = simplify_or(e[1])
        return e

    def apply_negative_absorption(e):
        if isinstance(e, And):
            e[0] = apply_negative_absorption(e[0])
            e[1] = apply_negative_absorption(e[1])
            if isinstance(e[1], Not) and isinstance(e[1][0], Or) and e[1][0][0] in e[0]:
                left = e[1][0][0]
                right = Or(e[0], e[1][0][1])
                return And(left, right)
        elif isinstance(e, Or):
            e[0] = apply_negative_absorption(e[0])
            e[1] = apply_negative_absorption(e[1])
            if isinstance(e[1], Not) and isinstance(e[1][0], And) and e[1][0][0] in e[0]:
                left = e[1][0][0]
                right = Or(e[0], e[1][0][1])
                return Or(left, right)
        return e

    def apply_absorption_neg_absorption(args):
        result = []
        for arg in args:
            if isinstance(arg, And):
                arg = apply_absorption(arg)
                arg = apply_negative_absorption(arg)
            elif isinstance(arg, Or):
                arg = apply_absorption(arg)
                arg = apply_negative_absorption(arg)
            result.append(arg)
        return result

    return apply_absorption_neg_absorption(args)

def absorb(self, args):
