    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorption(expr):
        if isinstance(expr, (tuple, list)):
            return tuple(absorption(e) for e in expr)
        elif isinstance(expr, str):
            if " & ( | ".replace(" ", "") in expr and " | ( & ".replace(" ", "") in expr:
                return expr
            elif expr.count(" & ") == 1 and expr.count(" | ") == 1:
                a, b = expr.split(" & ")
                c, d = expr.split(" | ")
                if a == c and b == d:
                    return a
            elif expr.count(" & ") == 1 and expr.count(" & (~") == 1:
                a, b = expr.split(" & ")
                c, d = expr.split(" & (~")
                if a.strip("())")[1:] == c.strip("()"):
                    return a.strip("()")
            elif expr.count(" | ") == 1 and expr.count(" | (~") == 1:
                a, b = expr.split(" | ")
                c, d = expr.split(" | (~")
                if a.strip("())")[1:] == c.strip("()"):
                    return a.strip("()")
        return expr

    return [absorption(expr) for expr in args]

