        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, tuple) and len(arg) == 2 and isinstance(arg[0], str) and isinstance(arg[1], str):
            op1, op2 = arg[0], arg[1]
            if op1 == 'and':
                if op2 == 'or':
                    new_args.append((op1, op1))
