import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Flatten the list of commands if it's nested
    if isinstance(commands, list) and isinstance(commands[0], list):
        commands = [item for sublist in commands for item in sublist]

    # Prepare the final command list
    final_command = [commands] + args

    # Run the command
    try:
        if hide_stderr:
            output = subprocess.check_output(final_command, cwd=cwd, stderr=subprocess.STDOUT, env=env)
        else:
            output = subprocess.check_output(final_command, cwd=cwd, env=env)
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed: {final_command}")
            print(f"Error: {e.output.decode('utf-8')}")
        raise
    else:
        if verbose and output:
            print(f"Command output: {output.decode('utf-8')}")
        return output.decode('utf-8')

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if verbose:
        print(f"Running command: {' '.join(commands + args)}")

    try:
        proc = subprocess.Popen(
            commands + args,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT if hide_stderr else subprocess.PIPE,
            env=env
        )
        output, stderr = proc.communicate()

        if proc.returncode != 0 and not hide_stderr:
            print(stderr.decode('utf-8'), file=sys.stderr)
        elif verbose:
            print(output.decode('utf-8'))

        return proc.returncode
    except Exception as e:
        print(f"Error running command: {e}", file=sys.stderr)
        return -1

