def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path.strip():
        return 'error: empty path'

    try:
        root, _, item = path.rpartition('/')
    except Exception as e:
        return str(e)

    namaste_file = os.path.join(root, item, '0', '*', '0=*.namaste')

    if os.path.exists(namaste_file):
        with open(namaste_file, 'r') as file:
            content = file.read().strip()
            if content == 'ocfl 1.0 storage':
                return 'root'
            elif content == 'ocfl 1.0 inventory':
                return 'object'
            elif content == 'ocfl 1.0 file':
                return 'file'

    return 'error: unknown type'

