def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """

    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for action_name, subparser in subparsers.items():
        original_remaining_args = remaining_args.copy()
        try:
            namespace, remaining_args = subparser.parse_known_args(remaining_args)
            parsed_args[action_name] = namespace
        except SystemExit:
            # Subparser consumed all remaining args, exit silently
            if remaining_args == original_remaining_args:
                parsed_args[action_name] = None
            else:
                parsed_args[action_name] = subparser.parse_args(remaining_args)
            remaining_args = []

    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """

    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for name, parser in subparsers.items():
        subparser_args = remaining_args[:]
        try:
            namespace, remaining_subparser_args = parser.parse_known_args(subparser_args)
            parsed_args[name] = namespace
            remaining_args = [arg for arg in remaining_args if arg not in subparser_args or arg in remaining_subparser_args]
        except SystemExit:
            continue

    return parsed_args, remaining_args

