    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_dict = {}
    for key, value in nodes:
        if key.value in merged_dict and isinstance(merged_dict[key.value], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
            merged_dict[key.value].value = deep_merge_nodes(list(zip(merged_dict[key.value].value, value.value)))
