def deep_merge_nodes(nodes):
    result = {}
    for key_node, value_node in nodes:
        if key_node.value in result:
            if isinstance(value_node, MappingNode) and isinstance(result[key_node.value], MappingNode):
                result[key_node.value] = deep_merge_nodes([
                    (result[key_node.value][key], value)
                    for key in result[key_node.value]
                ] + [
                    (key, value_node[key])
                    for key in value_node
                ])
            else:
                result[key_node.value] = value_node
        else:
            result[key_node.value] = value_node
    return result

