def size_to_bytes(size_str: str) -> int:
    size_parts = size_str[:-1].strip()
    multiplier = size_str[-1].upper()

    if not size_parts or not multiplier:
        raise ValueError("Invalid size format")

    size_parts = float(size_parts)

    if multiplier == 'B':
        return int(size_parts)
    elif multiplier == 'K':
        return int(size_parts * 1024)
    elif multiplier == 'M':
        return int(size_parts * 1024 ** 2)
    elif multiplier == 'G':
        return int(size_parts * 1024 ** 3)
    elif multiplier == 'T':
        return int(size_parts * 1024 ** 4)
    elif multiplier == 'P':
        return int(size_parts * 1024 ** 5)
    elif multiplier == 'E':
        return int(size_parts * 1024 ** 6)
    elif multiplier == 'Z':
        return int(size_parts * 1024 ** 7)
    elif multiplier == 'Y':
        return int(size_parts * 1024 ** 8)
    else:
        raise ValueError("Unknown unit: " + multiplier)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if size[-1].lower() in ['k', 'm', 'g', 't', 'p', 'e', 'z', 'y']:
        value = float(size[:-1])
        unit = size[-1].lower()
        if unit == 'k':
            return int(value * 1024)
        elif unit == 'm':
            return int(value * 1024 ** 2)
        elif unit == 'g':
            return int(value * 1024 ** 3)
        elif unit == 't':
            return int(value * 1024 ** 4)
        elif unit == 'p':
            return int(value * 1024 ** 5)
        elif unit == 'e':
            return int(value * 1024 ** 6)
        elif unit == 'z':
            return int(value * 1024 ** 7)
        elif unit == 'y':
            return int(value * 1024 ** 8)
    else:
        return int(size)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

