def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if number == 0:
        return alphabet[0] * (padding or 1) if padding is not None else alphabet[0]
    digits = []
    base = len(alphabet)
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base
    if padding is not None and len(digits) < padding:
        digits.extend([alphabet[0]] * (padding - len(digits)))
    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    base = len(alphabet)
    if padding is None:
        padding = 1
    if not isinstance(padding, int) or padding <= 0:
        raise ValueError("padding must be a positive integer")

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if len(result) > padding:
        raise ValueError("number too large for the given padding")

    result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

