    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop(0)
        seen.add(c)

        for sc in c.__subclasses__():
            if sc not in seen:
                queue.append(sc)

    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        if c not in seen:
            seen.add(c)
            queue.update(c.__subclasses__())

    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    base = len(alphabet)
    inverse_alphabet = {char: index for index, char in enumerate(alphabet)}
    number = 0
    for char in string:
        number = number * base + inverse_alphabet[char]
    return number

