        'seconds': 'seconds',
        'minutes': 'minutes',
        'hours': 'hours',
        'days': 'days',
        'weeks': 'weeks',
        'months': 'months',
        'years': 'years'
    }

    for unit, attr in units.items():
        if frequency.endswith(unit):
            try:
                value = int(frequency[:-len(unit)].strip())
                return datetime.timedelta(**{attr: value})
            except ValueError:
                pass

    raise ValueError(f"Invalid frequency string: {frequency}")

