    """
    local_ips = ['127.0.0.1', '::1']
    try:
        resolved_ips = socket.getaddrinfo(host, None, socket.AF_INET6)
        for item in resolved_ips:
            local_ips.append(item[-1][0])
    except socket.gaierror:
        pass
    try:
        resolved_ips = socket.getaddrinfo(host, None, socket.AF_INET)
        for item in resolved_ips:
