    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import toml
    import yaml
    import logging

    config_dict = {}
    log_records = []

    for config_file in config_filenames:
        if not os.path.exists(config_file):
            log_record = logging.LogRecord("load_configurations", logging.ERROR, filename=None, lineno=None, msg=f"Configuration file not found: {config_file}", args=(), exc_info=None)
            log_records.append(log_record)
            continue

        try:
            with open(config_file) as fd:
                raw_config = fd.read()
                if config_file.endswith('.toml'):
                    config = toml.loads(raw_config)
                elif config_file.endswith('.yaml') or config_file.endswith('.yml'):
                    config = yaml.safe_load(raw_config)
                else:
                    raise ValueError(f"Unsupported configuration file format: {config_file}")

                if overrides:
                    config.update(overrides)

                if resolve_env:
                    for key, value in config.items():
                        if isinstance(value, str) and value.startswith('${'):
                            var_name = value[2:-1]
                            if var_name in os.environ:
                                config[key] = os.environ[var_name]

                config_dict[config_file] = config

        except (TOMLDecodeError, yaml.YAMLError, ValueError) as e:
            log_record = logging.LogRecord("load_configurations", logging.ERROR, filename=None, lineno=None, msg=f"Error parsing {config_file}: {e}", args=(), exc_info=None)
            log_records.append(log_record)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_dict = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename) as fd:
                raw_config = fd.read()
            config = yaml.safe_load(raw_config) if filename.endswith('.yaml') else toml.loads(raw_config)
            if overrides:
                config.update(overrides)
            if resolve_env:
                config = resolve_environment_variables(config)
            config_dict[filename] = config
        except Exception as e:
            error_record = logging.LogRecord('load_configurations', logging.ERROR, filename, None, str(e), None, None)
            errors.append(error_record)

    return config_dict, errors

