def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw_config = fd.read()
                config = toml.loads(raw_config)
                if overrides:
                    config.update(overrides)
                if resolve_env:
                    config = resolve_environment_variables(config)
                config_dict[filename] = config
            except Exception as e:
                log_record = logging.LogRecord(name=__name__, level=logging.ERROR,
                                                pathname=filename, lineno=0,
                                                msg=str(e), args=(), exc_info=None)
                log_records.append(log_record)

    return config_dict, log_records

def resolve_environment_variables(config):
    import os
    for key, value in config.items():
        if isinstance(value, str):
            config[key] = os.path.expandvars(value)
        elif isinstance(value, dict):
            config[key] = resolve_environment_variables(value)
    return config

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, bytes):
        return obj
    elif isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return str(obj).encode('utf-8')

