def scale(self, other=None):
        if other is None:
            return self._scale
        elif isinstance(other, numbers.Number) and other > 0:
            if self._scale == 0:
                raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")
            else:
                self._scale = other
                for field in self.fields:
                    field.scale(self._scale)
        else:
            raise ValueError("Invalid scale value provided.")

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import zope.interface
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not provide {iface}")

    for name, method in iface.__dict__.items():
        if callable(method):
            if name not in candidate.__dict__:
                errors.append(f"{candidate} does not define method {name}")
            else:
                cand_method = candidate.__dict__[name]
                if not inspect.isfunction(cand_method):
                    errors.append(f"{candidate}.{name} is not a function")
                else:
                    cand_signature = inspect.signature(cand_method)
                    if cand_signature != inspect.signature(method):
                        errors.append(f"Signature of {candidate}.{name} does not match {iface}.{name}")

    for name, attr in iface.__dict__.items():
        if not callable(attr):
            if name not in candidate.__dict__:
                errors.append(f"{candidate} does not define attribute {name}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        # Perform a more lenient check
        return all(attr in candidate.__dict__ for attr in iface.__dict__)
    else:
        # Perform a strict check
        return all(getattr(candidate, attr, None) is not None for attr in iface.__dict__)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    for method_name in iface.__dict__:
        if not method_name.startswith('__'):
            method = getattr(iface, method_name)
            if not callable(method):
                continue
            method_to_verify = getattr(candidate, method_name, None)
            if not method_to_verify:
                if not tentative:
                    raise AttributeError(f"Missing required method '{method_name}' in candidate")
                else:
                    return False
            if not callable(method_to_verify):
                raise AttributeError(f"Method '{method_name}' in candidate is not callable")
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        if iface in candidate.__dict__:
            return True
    else:
        if iface in candidate.__dict__ and callable(candidate.__dict__[iface]):
            return True
    return False

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    for attr in iface.__dict__:
        if not attr.startswith('__'):
            if not hasattr(candidate, attr):
                return False
            if tentative:
                if not callable(getattr(candidate, attr)):
                    return False
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    from Acquisition import aq_base
    base = aq_base(candidate)

    if hasattr(base, '__implements__'):
        if iface in base.__implements__:
            return True

    if iface.isImplementedBy(candidate):
        return True

    if tentative:
        return False

    raise TypeError("%s does not implement %s" % (candidate, iface))

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    for base in bases:
        meta = getattr(base, '__metaclass__', None)
        if meta is not None:
            return meta

    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    metaclass = explicit_mc
    for base in bases:
        base_metaclass = getattr(base, "__metaclass__", None)
        if base_metaclass:
            metaclass = base_metaclass

    return metaclass if metaclass is not None else type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    if explicit_mc is not None:
        return explicit_mc

    return bases[0].__class__

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    for base in bases:
        if explicit_mc is not None:
            return explicit_mc
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__
    if hasattr(__builtins__, '__metaclass__'):
        return __builtins__.__metaclass__
    return type

import sys

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    if not bases:
        import __builtin__ as builtins
        return builtins.object.__class__

    return bases[0].__class__

def pop(self, key, default=None):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    return self._dict.pop(key)

