import urllib2
from typing import Optional
from urllib.parse import urlparse

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    scheme, netloc, path, query, fragment = urlparse(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = urllib2.Request(url, method='HEAD')
    req.add_header('Host', netloc)
    try:
        resp = urllib2.urlopen(req)
        try:
            return resp.info().get('content-type', '')
        finally:
            resp.close()
    except urllib2.URLError:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    try:
        req = urllib.request.Request(url, method='HEAD', headers={'Host': netloc})
        with urllib.request.urlopen(req) as resp:
            return resp.info().get('Content-Type', None)
    except urllib.error.URLError:
        return None

