import json
from xml.etree import ElementTree as ET
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON
        data = json.loads(document)
        if "links" in data:
            return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD
        root = ET.fromstring(document)
        data = {}
        for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd/1.0}link"):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                if rel not in data:
                    data[rel] = []
                data[rel].append(href)
        return data
    return {}

