def parse_xrd(document: str) -> Dict:
    """
    Parse XRD document.
    """
    xrd = ElementTree.fromstring(document)
    properties = xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property")
    result = {}
    for prop in properties:
        result[prop.get("name")] = prop.text
    return result

