def parse_xrd(document: str) -> Dict:
    root =.fromstring(document.encode("utf-8"))
    if "XRD" not in root.tag:
        raise ValueError("Not a valid XRD document")
    result = {}
    for link in root.findall("{urn:xrd:spec:1.0}Link"):
        rel = link.get("rel")
        href = link.get("href")
        if rel and href:
            result[rel] = href
    return result

