def parse_xrd(document: str) -> Dict:
    xrd = etree.fromstring(document)
    links = xrd.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
    parsed_data = {}
    for link in links:
        rel = link.get("rel")
        if rel:
            parsed_data[rel] = link.get("template") or link.get("href")
    return parsed_data

