    if "headers" in kwargs:
        # Update from kwargs
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })
    try:
        if method.lower() == "post":
            response = requests.post(url, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported method: {method}")
        logger.debug(f"send_document: response status code {response.status_code}")
        return response.status_code, None
    except RequestException as ex:
        logger.debug(f"send_document: exception {ex}")
        return None, ex

def dict_insert(dic, val, key, *keys):
    if not keys:
        dic[key] = val
        return dic

    if key not in dic:
        dic[key] = {}

    dic[key] = dict_insert(dic[key], val, *keys)
    return dic

def dict_insert(dic, val, key, *keys):
    current_dict = dic
    key_list = [key] + list(keys)
    for k in key_list[:-1]:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]
    current_dict[key_list[-1]] = val

