def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        include_map = {}
        for key, value in parser_dict.items():
            if 'include' in value:
                include_key = value['include']
                if include_key in parser_dict:
                    include_map[key] = parser_dict[include_key]
                else:
                    raise ValueError(f"Include key '{include_key}' not found in parser_dict")
        for key, value in include_map.items():
            parser_dict[key] = {**value, **parser_dict[key]}
            del parser_dict[key]['include']

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_dict = parser_dict.get('include', {})
    for key, value in include_dict.items():
        parser_dict[key] = self._merge_dicts(parser_dict.get(key, {}), value)
    return parser_dict

def _merge_dicts(self, a, b):
    """Merges two dictionaries recursively. """
    for key in b:
        if key in a:
            if isinstance(a[key], dict) and isinstance(b[key], dict):
                self._merge_dicts(a[key], b[key])
            else:
                a[key] = b[key]
        else:
            a[key] = b[key]
    return a

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if key == 'include':
