    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _get_properties(file_path):
        with open(file_path, 'r') as file:
            data = json.load(file)
        return data

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    properties = {}
    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                properties.update(_get_properties(file_path))

    return flatten_dict(properties)

